import '../../experiment/sensor_lab/domain/lab_experiment_definition.dart';
import '../domain/visual_intent.dart';

/// Validation report generated by [VisualSchemaRegistry].
final class VisualValidationReport {
  const VisualValidationReport({
    required this.isValid,
    required this.errors,
    this.validatedIntent,
  });

  final bool isValid;
  final List<String> errors;
  final VisualIntent? validatedIntent;

  @override
  String toString() =>
      'VisualValidationReport(valid: $isValid, errors: $errors)';
}

/// Registry and validator for all visual artifact schemas in Mentora 2.0.
///
/// Enforces strict structural schema constraints and physical domain boundaries
/// before any visual is dispatched to native renderers.
final class VisualSchemaRegistry {
  const VisualSchemaRegistry({
    Set<String>? allowedSimulationIds,
  }) : _allowedSimulationIds = allowedSimulationIds ?? _defaultAllowedSimulationIds;

  final Set<String> _allowedSimulationIds;

  static const _defaultAllowedSimulationIds = {
    'phet-bending-light',
    'phet-forces-motion',
    'phet-balancing-chemical-equations',
    'phet-build-an-atom',
    'phet-fraction-matcher',
  };

  /// Validates a [VisualIntent] against structural schema and domain rules.
  VisualValidationReport validate(VisualIntent intent) {
    final errors = <String>[];

    // 1. Schema version check
    if (intent.schemaVersion != 1) {
      errors.add('Unsupported schema version: ${intent.schemaVersion}. Expected: 1.');
    }

    // 2. Type validity
    if (intent.type == VisualType.unknown) {
      errors.add('Unrecognized or unsupported visual type: ${intent.type.identifier}.');
    }

    // 3. Domain validation per visual type
    switch (intent.type) {
      case VisualType.motionTrajectory:
        _validateMotionTrajectory(intent, errors);
        break;

      case VisualType.simulationLauncher:
        _validateSimulationLauncher(intent, errors);
        break;

      case VisualType.stepsSolution:
        _validateStepsSolution(intent, errors);
        break;

      case VisualType.mathFunctionGraph:
        _validateFunctionGraph(intent, errors);
        break;

      case VisualType.physicsForceDiagram:
        _validateForceDiagram(intent, errors);
        break;

      case VisualType.labSetup:
        _validateLabSetup(intent, errors);
        break;

      case VisualType.conceptSequence:
      case VisualType.unknown:
        break;
    }

    return VisualValidationReport(
      isValid: errors.isEmpty,
      errors: errors,
      validatedIntent: errors.isEmpty ? intent : null,
    );
  }

  void _validateMotionTrajectory(VisualIntent intent, List<String> errors) {
    final inputs = intent.inputs;
    final scenario = intent.scenario.toLowerCase();

    if (scenario.isEmpty) {
      errors.add('motion.trajectory requires a non-empty scenario identifier.');
    }

    final rawV = inputs['initial_velocity_mps'] ?? inputs['launch_velocity_mps'] ?? inputs['u'];
    if (rawV != null) {
      final v = (rawV as num).toDouble();
      if (v < 0 || v > 1000) {
        errors.add('Initial velocity out of realistic domain bounds [0, 1000] m/s: $v.');
      }
    }

    final rawG = inputs['gravity_mps2'] ?? inputs['g'];
    if (rawG != null) {
      final g = (rawG as num).toDouble();
      if (g <= 0 || g > 50) {
        errors.add('Gravity out of realistic domain bounds (0, 50] m/s²: $g.');
      }
    }

    final rawAngle = inputs['launch_angle_deg'] ?? inputs['theta'];
    if (rawAngle != null) {
      final angle = (rawAngle as num).toDouble();
      if (angle < 0 || angle > 90) {
        errors.add('Launch angle out of domain bounds [0, 90] degrees: $angle.');
      }
    }

    final rawMass = inputs['mass_kg'] ?? inputs['m'];
    if (rawMass != null) {
      final mass = (rawMass as num).toDouble();
      if (mass <= 0) {
        errors.add('Mass must be strictly positive: $mass kg.');
      }
    }
  }

  void _validateSimulationLauncher(VisualIntent intent, List<String> errors) {
    final inputs = intent.inputs;
    final simId = (inputs['simulation_id'] ?? inputs['id'] ?? intent.scenario).toString().trim();

    if (simId.isEmpty) {
      errors.add('simulation.launcher requires a simulation_id.');
      return;
    }

    if (!_allowedSimulationIds.contains(simId) && !simId.startsWith('phet-')) {
      errors.add('Simulation ID "$simId" is not verified in local catalog.');
    }
  }

  void _validateStepsSolution(VisualIntent intent, List<String> errors) {
    final rawSteps = intent.inputs['steps'];
    if (rawSteps == null || rawSteps is! List || rawSteps.isEmpty) {
      errors.add('steps.solution requires a non-empty list of steps.');
    }
  }

  void _validateFunctionGraph(VisualIntent intent, List<String> errors) {
    final formula = intent.inputs['formula'] ?? intent.inputs['function'] ?? intent.scenario;
    if (formula.toString().trim().isEmpty) {
      errors.add('math.function_graph requires a valid formula or function identifier.');
    }
  }

  void _validateForceDiagram(VisualIntent intent, List<String> errors) {
    final forces = intent.inputs['forces'];
    if (forces != null && forces is! List && forces is! Map) {
      errors.add('physics.force_diagram requires structured force vector inputs.');
    }
  }

  void _validateLabSetup(VisualIntent intent, List<String> errors) {
    final expId = (intent.inputs['experiment_id'] ?? intent.inputs['id'] ?? intent.scenario)
        .toString()
        .trim();
    if (expId.isEmpty) {
      errors.add('lab.setup requires a non-empty experiment_id.');
      return;
    }
    if (LabExperimentCatalog.getById(expId) == null && !expId.startsWith('exp_')) {
      errors.add('Experiment ID "$expId" is not an approved experiment in the catalog.');
    }
  }
}
